+template <int Width, bool Trusted>
+__device__ __forceinline__ Param row_parameters(const Args& a, int row) {
+  return {
+      a.meta[row * 64 + Width],
+      a.fine_scale[row * Width],
+      a.fine_scale[row * Width + 1],
+      a.raw[row],
